"use client";

import { Collapsible } from "@base-ui/react/collapsible";
import { Tooltip } from "@base-ui/react/tooltip";
import { ChevronDown, FileText, Globe } from "lucide-react";
import { useEffect, useEffectEvent, useId, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { thinkingStateCss, thinkingStateDefaults, thinkingStateStyleHref } from "@/components/ui/kalos-thinking-state-styles";

export type ThinkingSource = {
  label: string;
  href?: string;
  icon?: ReactNode;
  tooltip?: string;
};

export type ThinkingStep =
  | { kind: "search"; label: string; activeLabel?: string; sources?: readonly ThinkingSource[]; moreSources?: readonly ThinkingSource[] }
  | { kind: "step"; label: string };

export type KalosThinkingStateProps = {
  steps: readonly ThinkingStep[];
  doneLabel?: string;
  stepMs?: number;
  loop?: boolean;
  collapseOnDone?: boolean;
  onDone?: (seconds: number) => void;
  locale?: "zh-CN" | "en-US";
  className?: string;
};

const labels = {
  "zh-CN": {
    thinking: "正在思考", worked: "思考用时", done: "思考完成",
    time: (seconds: number) => `${seconds} 秒`,
    more: (count: number) => `+${count} 个来源`, less: "收起来源",
  },
  "en-US": {
    thinking: "Thinking", worked: "Worked for", done: "Finished thinking",
    time: (seconds: number) => `${seconds}s`,
    more: (count: number) => `+${count} more`, less: "Show fewer sources",
  },
};

const initialProgress = { cycle: 0, visible: 0, seconds: 0, done: false };

function SearchNode() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
    <path d="M12.2 21a9 9 0 1 1 8.7-10.3M3.7 8.7h15.8M4.8 16h4.1M12 3C8.2 6.8 7.6 16.3 12 21m0-18c1.6 1.9 2.6 4.4 2.9 7" />
    <circle cx="16.3" cy="15.9" r="3.3" />
    <path d="m18.7 18.3 2.8 2.8" />
  </svg>;
}

function SourceChip({ source, index, container }: {
  source: ThinkingSource;
  index: number;
  container: Tooltip.Portal.Props["container"];
}) {
  const tooltipId = useId();
  const [tooltipOpen, setTooltipOpen] = useState(false);
  const address = source.href?.replace(/^https?:\/\//i, "").replace(/\/$/, "");
  const tooltip = source.tooltip ?? (address || source.href);
  const style = { "--kts-chip-index": index } as CSSProperties;
  const content = <>
    <span className="kalos-thinking-source-icon" data-brand={source.icon ? "" : undefined} aria-hidden="true">
      {source.icon ?? (source.href ? <Globe /> : <FileText />)}
    </span>
    <span>{source.label}</span>
  </>;
  const chip = source.href
    ? <a className="kalos-thinking-chip" style={style} href={source.href} target="_blank" rel="noreferrer">{content}</a>
    : <span className="kalos-thinking-chip" style={style} tabIndex={tooltip ? 0 : undefined}>{content}</span>;

  return tooltip ? <Tooltip.Root onOpenChange={setTooltipOpen}>
    <Tooltip.Trigger render={chip} aria-describedby={tooltipOpen ? tooltipId : undefined} />
    <Tooltip.Portal container={container}>
      <Tooltip.Positioner className="kalos-thinking-tooltip-positioner" side="top" sideOffset={6} collisionPadding={8}>
        <Tooltip.Popup className="kalos-thinking-tooltip" id={tooltipId} role="tooltip">{tooltip}</Tooltip.Popup>
      </Tooltip.Positioner>
    </Tooltip.Portal>
  </Tooltip.Root> : chip;
}

function SearchSources({ sources = [], moreSources = [], copy, container }: {
  sources?: readonly ThinkingSource[];
  moreSources?: readonly ThinkingSource[];
  copy: (typeof labels)[keyof typeof labels];
  container: Tooltip.Portal.Props["container"];
}) {
  const [expanded, setExpanded] = useState(false);
  const moreId = useId();
  if (!sources.length && !moreSources.length) return null;

  return <div className="kalos-thinking-sources">
    {sources.map((source, index) => <SourceChip key={index} source={source} index={index} container={container} />)}
    {moreSources.length ? <>
      <div className="kalos-thinking-extra" id={moreId} hidden={!expanded}>
        {expanded ? moreSources.map((source, index) => <SourceChip key={index} source={source} index={index} container={container} />) : null}
      </div>
      <button
        type="button"
        className="kalos-thinking-chip kalos-thinking-more"
        style={{ "--kts-chip-index": sources.length } as CSSProperties}
        aria-controls={moreId}
        aria-expanded={expanded}
        onClick={() => setExpanded(value => !value)}
      >{expanded ? copy.less : copy.more(moreSources.length)}</button>
    </> : null}
  </div>;
}

export function KalosThinkingState({
  steps,
  doneLabel,
  stepMs = thinkingStateDefaults.stepMs,
  loop = false,
  collapseOnDone = false,
  onDone,
  locale = "zh-CN",
  className,
}: KalosThinkingStateProps) {
  const [cycle, setCycle] = useState(0);
  const [progress, setProgress] = useState(initialProgress);
  const [open, setOpen] = useState(true);
  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const autoCollapsed = useRef(false);
  const { visible, seconds, done } = progress.cycle === cycle ? progress : initialProgress;
  const copy = labels[locale];

  const getTiming = useEffectEvent(() => {
    const delay = Number.isFinite(stepMs) ? Math.max(0, stepMs) : thinkingStateDefaults.stepMs;
    const searchLead = steps[0]?.kind === "search" ? Math.min(thinkingStateDefaults.searchLead, delay * 0.6) : 0;
    return { delay, searchLead };
  });

  const advance = useEffectEvent((startedAt: number, currentCycle: number, { delay, searchLead }: ReturnType<typeof getTiming>) => {
    const elapsed = performance.now() - startedAt;
    const revealed = delay ? 1 + Math.floor(Math.max(0, elapsed - searchLead) / delay) : steps.length + 1;
    const completed = !steps.length || revealed > steps.length;
    const seconds = Math.floor(elapsed / 1000);
    setProgress({ cycle: currentCycle, visible: Math.min(steps.length, revealed), seconds, done: completed });

    if (completed) {
      onDone?.(seconds);
      return null;
    }

    const nextStep = searchLead + revealed * delay;
    const nextSecond = (seconds + 1) * 1000;
    return Math.max(1, Math.ceil(Math.min(nextStep, nextSecond) - elapsed));
  });

  useEffect(() => {
    const startedAt = performance.now();
    const timing = getTiming();
    const tick = () => {
      const wait = advance(startedAt, cycle, timing);
      if (wait !== null) timer = window.setTimeout(tick, wait);
    };
    let timer = window.setTimeout(tick, 0);
    return () => window.clearTimeout(timer);
  }, [cycle]);

  const collapse = useEffectEvent(() => {
    if (!open) return;
    if (panelRef.current?.contains(document.activeElement)) triggerRef.current?.focus();
    autoCollapsed.current = true;
    setOpen(false);
  });

  useEffect(() => {
    if (!done || !collapseOnDone) return;
    const timer = window.setTimeout(() => collapse(), thinkingStateDefaults.autoCollapseDelay);
    return () => window.clearTimeout(timer);
  }, [cycle, done, collapseOnDone]);

  useEffect(() => {
    if (!done || !loop) return;
    const timer = window.setTimeout(() => {
      if (panelRef.current?.contains(document.activeElement)) triggerRef.current?.focus();
      if (autoCollapsed.current) setOpen(true);
      autoCollapsed.current = false;
      setCycle(current => current + 1);
    }, thinkingStateDefaults.loopDelay);
    return () => window.clearTimeout(timer);
  }, [cycle, done, loop]);

  const time = copy.time(seconds);
  return <Collapsible.Root
    ref={rootRef}
    className={cn("kalos-thinking-state", className)}
    data-state={done ? "done" : "thinking"}
    open={open}
    onOpenChange={next => {
      autoCollapsed.current = false;
      setOpen(next);
    }}
  >
    <style href={thinkingStateStyleHref} precedence="kalos">{thinkingStateCss}</style>
    <Collapsible.Trigger
      ref={triggerRef}
      className="kalos-thinking-header"
      aria-label={done ? `${copy.worked} ${time}` : copy.thinking}
    >
      <svg className="kalos-thinking-mark" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true">
        {Array.from({ length: 9 }, (_, index) => <rect
          key={index}
          x={2.5 + index % 3 * 4}
          y={2.5 + Math.floor(index / 3) * 4}
          width="3"
          height="3"
          rx=".75"
        />)}
      </svg>
      {done
        ? <span key="total" className="kalos-thinking-header-copy">{copy.worked} {time}</span>
        : <span key="live" className="kalos-thinking-header-copy">
          <span className="kalos-thinking-heading" data-shimmer={copy.thinking}>{copy.thinking}</span>
          <span className="kalos-thinking-time" aria-hidden="true">{time}</span>
        </span>}
      <ChevronDown className="kalos-thinking-chevron" aria-hidden="true" />
    </Collapsible.Trigger>
    <Collapsible.Panel
      ref={panelRef}
      className="kalos-thinking-panel"
      inert={!open}
      keepMounted
      render={({ hidden, ...panelProps }) => <div {...panelProps} data-fold-hidden={hidden || undefined} />}
    >
      <Tooltip.Provider delay={250} timeout={200}>
        <ol key={cycle} className="kalos-thinking-timeline" aria-live="polite" aria-relevant="additions">
          {steps.slice(0, visible).map((step, index) => {
            const active = !done && index === visible - 1;
            const label = active && step.kind === "search" ? step.activeLabel ?? step.label : step.label;
            return <li key={index} className="kalos-thinking-row" data-active={active ? "" : undefined}>
              <span className="kalos-thinking-node" aria-hidden="true">
                {step.kind === "search" ? <SearchNode /> : <i />}
              </span>
              <div className="kalos-thinking-step">
                <span className="kalos-thinking-label" data-shimmer={active ? label : undefined} dir="auto">{label}</span>
                {step.kind === "search" ? <SearchSources sources={step.sources} moreSources={step.moreSources} copy={copy} container={rootRef} /> : null}
              </div>
            </li>;
          })}
          {done ? <li className="kalos-thinking-row kalos-thinking-done">
            <span className="kalos-thinking-node" aria-hidden="true">
              <svg viewBox="0 0 16 16" fill="none">
                <circle cx="8" cy="8" r="6.5" fill="currentColor" />
                <path d="m5 8.1 1.9 1.9 4-4.1" pathLength="1" strokeWidth="1.35" strokeLinecap="round" strokeLinejoin="round" />
              </svg>
            </span>
            <span dir="auto">{doneLabel ?? copy.done}</span>
          </li> : null}
        </ol>
      </Tooltip.Provider>
    </Collapsible.Panel>
  </Collapsible.Root>;
}

// Generated from design tokens and design/thinking-state.css.
export const thinkingStateDefaults = {"width":420,"chipRadius":6,"stepMs":1300,"searchLead":760,"loopDelay":2600,"autoCollapseDelay":620,"enterDuration":520,"foldOpenDuration":340,"foldCloseDuration":200,"foldOpenEase":"cubic-bezier(0.22, 0.61, 0.36, 1)","shimmerDuration":1600,"pulseDuration":1000,"chipDuration":420,"chipLead":120,"chipStagger":160,"extraChipStagger":70,"checkDuration":460,"tickDuration":360,"tickDelay":180,"ease":"cubic-bezier(0.22, 1, 0.36, 1)"} as const;
export const thinkingStateStyleHref = "kalos-thinking-state-09b86e5e68f0";
export const thinkingStateCss = ".kalos-thinking-state{font-family:Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", ByteSans, Arial, "Helvetica Neue", -apple-system, BlinkMacSystemFont, "noto sans", Helvetica, sans-serif;font-size:13px;line-height:20px;--kts-surface:var(--card, #ffffff);--kts-ink:var(--foreground, rgba(0, 0, 0, 0.88));--kts-muted:var(--muted-foreground, rgba(0, 0, 0, 0.61));--kts-rail:var(--border, #00000014);--kts-accent:rgba(0, 96, 226, 0.765);--kts-on-accent:#ffffff;--kts-thinking:rgba(0, 0, 0, 0.45);--kts-shimmer:rgba(255, 255, 255, 0.82);--kts-node:rgba(0, 0, 0, 0.27);--kts-chip-hover:color-mix(in srgb, var(--kts-surface) 97%, #000);--kts-chip-shadow:0 0 0 0.5px rgba(0, 0, 0, 0.06), 0 1px 2px rgba(0, 0, 0, 0.06);--kts-logo-edge:rgba(0, 0, 0, 0.1);--kts-more-edge:rgba(0, 0, 0, 0.06);--kts-more-hover:rgba(0, 0, 0, 0.06);--kts-popup-surface:#ffffff;--kts-popup-shadow:0 0 0 0.5px rgba(0, 0, 0, 0.08), 0 2px 5px rgba(0, 0, 0, 0.07), 0 12px 28px -10px rgba(0, 0, 0, 0.16);--kts-enter-duration:520ms;--kts-fold-open-duration:340ms;--kts-fold-close-duration:200ms;--kts-shimmer-duration:1600ms;--kts-pulse-duration:1000ms;--kts-chip-duration:420ms;--kts-chip-lead:120ms;--kts-chip-stagger:160ms;--kts-extra-chip-stagger:70ms;--kts-check-duration:460ms;--kts-tick-duration:360ms;--kts-tick-delay:180ms;--kts-width:420px;--kts-chip-radius:6px;--kts-ease:cubic-bezier(0.22, 1, 0.36, 1);--kts-fold-open-ease:cubic-bezier(0.22, 0.61, 0.36, 1)}
:where(.dark,[data-theme=dark]) .kalos-thinking-state{--kts-surface:var(--card, #1c1c1e);--kts-ink:var(--foreground, rgba(255, 255, 255, 0.9));--kts-muted:var(--muted-foreground, rgba(255, 255, 255, 0.62));--kts-rail:var(--border, #ffffff1a);--kts-accent:#4fb0fe;--kts-on-accent:#1a2844;--kts-thinking:rgba(255, 255, 255, 0.46);--kts-shimmer:#ffffff;--kts-node:rgba(255, 255, 255, 0.27);--kts-chip-hover:color-mix(in srgb, var(--kts-surface) 96%, #fff);--kts-chip-shadow:0 0 0 0.5px rgba(255, 255, 255, 0.1), 0 1px 2px rgba(0, 0, 0, 0.4);--kts-logo-edge:rgba(255, 255, 255, 0.14);--kts-more-edge:rgba(255, 255, 255, 0.08);--kts-more-hover:rgba(255, 255, 255, 0.08);--kts-popup-surface:#232326;--kts-popup-shadow:0 0 0 0.5px rgba(255, 255, 255, 0.12), 0 12px 28px -10px rgba(0, 0, 0, 0.6)}
.kalos-thinking-state {
  box-sizing: border-box;
  width: 100%;
  max-width: var(--kts-width);
  min-width: 0;
  color: var(--kts-ink);
}

.kalos-thinking-header {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  max-width: 100%;
  gap: 8px;
  padding-block: 0;
  padding-inline: 0 6px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: var(--kts-muted);
  font: inherit;
  font-weight: 500;
  text-align: start;
  cursor: pointer;
  transition: color 160ms ease;
}

.kalos-thinking-header:is(:hover, :focus-visible),
.kalos-thinking-state[data-state="done"] .kalos-thinking-header {
  color: var(--kts-ink);
}

.kalos-thinking-header-copy {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  animation: kalos-thinking-enter var(--kts-chip-duration) var(--kts-ease) both;
}

.kalos-thinking-header:focus-visible,
.kalos-thinking-chip:focus-visible {
  outline: 1px solid var(--kts-accent);
  outline-offset: 2px;
}

.kalos-thinking-mark {
  display: block;
  flex: none;
  width: 16px;
  height: 16px;
  color: var(--kts-accent);
}

.kalos-thinking-mark > rect:nth-child(odd) { --kts-pixel-delay: -420ms; }
.kalos-thinking-mark > rect:nth-child(3n) { --kts-pixel-delay: -840ms; }
.kalos-thinking-mark > rect:nth-child(5) { --kts-pixel-delay: -1200ms; }
.kalos-thinking-state[data-state="thinking"] .kalos-thinking-mark > rect {
  animation: kalos-thinking-pixel var(--kts-shimmer-duration) var(--kts-pixel-delay, 0ms) ease-in-out infinite;
}

.kalos-thinking-time {
  flex: none;
  color: var(--kts-node);
  font-weight: 400;
  font-variant-numeric: tabular-nums;
}

.kalos-thinking-header .kalos-thinking-chevron {
  flex: none;
  width: 12px;
  height: 12px;
  color: var(--kts-thinking);
  opacity: 0;
  transition: opacity 160ms ease, rotate 260ms var(--kts-ease);
}

.kalos-thinking-header[aria-expanded="false"] .kalos-thinking-chevron { rotate: -90deg; }
.kalos-thinking-header[aria-expanded="false"]:dir(rtl) .kalos-thinking-chevron { rotate: 90deg; }
.kalos-thinking-header:is(:hover, :focus-visible) .kalos-thinking-chevron { opacity: 1; }

.kalos-thinking-panel[data-starting-style],
.kalos-thinking-panel[data-ending-style] {
  height: 0;
}

.kalos-thinking-panel {
  height: var(--collapsible-panel-height, auto);
  overflow-y: clip;
  transition: height var(--kts-fold-open-duration) var(--kts-fold-open-ease);
}

.kalos-thinking-panel[data-ending-style] {
  transition-duration: var(--kts-fold-close-duration);
  transition-timing-function: var(--kts-ease);
}

/* Keep the completed step animations from restarting when the inert panel reopens. */
.kalos-thinking-panel[data-fold-hidden] {
  height: 0;
  visibility: hidden;
}

.kalos-thinking-timeline {
  margin: 0;
  padding: 5px 0 4px;
  list-style: none;
}

.kalos-thinking-timeline:empty { padding: 0; }

.kalos-thinking-row {
  position: relative;
  display: grid;
  grid-template-columns: 16px minmax(0, 1fr);
  align-items: start;
  gap: 8px;
  min-height: 32px;
  padding: 3px 2px 9px 0;
  color: var(--kts-muted);
}

.kalos-thinking-row::after {
  position: absolute;
  inset-block: 23px -3px;
  inset-inline-start: 7.5px;
  width: 1px;
  border-radius: 1px;
  background: var(--kts-rail);
  transform: scaleY(1);
  transform-origin: top;
  transition: transform var(--kts-enter-duration) var(--kts-ease);
  content: "";
}

.kalos-thinking-row:last-child::after { transform: scaleY(0); }

.kalos-thinking-row > * {
  min-width: 0;
  overflow-wrap: anywhere;
  animation: kalos-thinking-enter var(--kts-enter-duration) var(--kts-ease) both;
}

.kalos-thinking-node {
  display: grid;
  place-items: center;
  width: 16px;
  height: 20px;
  color: var(--kts-thinking);
}

.kalos-thinking-node > svg { width: 16px; height: 16px; }

.kalos-thinking-node > i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--kts-node);
}

.kalos-thinking-row[data-active] .kalos-thinking-node > i {
  width: 6px;
  height: 6px;
  border-radius: 1.5px;
  background: var(--kts-accent);
  animation: kalos-thinking-pulse var(--kts-pulse-duration) ease-in-out infinite;
}

.kalos-thinking-label { display: inline-block; max-width: 100%; }

:is(.kalos-thinking-heading, .kalos-thinking-label)[data-shimmer] {
  position: relative;
  color: var(--kts-thinking);
}

:is(.kalos-thinking-heading, .kalos-thinking-label)[data-shimmer]::after {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(90deg, transparent 37%, var(--kts-shimmer) 50%, transparent 63%) 100% / 300% 100%;
  background-clip: text;
  color: transparent;
  animation: kalos-thinking-shimmer var(--kts-shimmer-duration) linear infinite;
  content: attr(data-shimmer) / "";
}

@media (forced-colors: active) {
  :is(.kalos-thinking-heading, .kalos-thinking-label)[data-shimmer]::after { display: none; }
}

.kalos-thinking-sources {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
  margin-block: 6px 3px;
}

.kalos-thinking-extra:not([hidden]) {
  display: contents;
  --kts-chip-lead: 0ms;
  --kts-chip-stagger: var(--kts-extra-chip-stagger);
}

.kalos-thinking-chip {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  min-width: 0;
  max-width: 100%;
  min-height: 26px;
  gap: 6px;
  padding-block: 5px;
  padding-inline: 6px 8px;
  border: 0;
  border-radius: var(--kts-chip-radius);
  background-color: var(--kts-surface);
  color: var(--kts-ink);
  box-shadow: var(--kts-chip-shadow);
  font: inherit;
  font-size: 12px;
  line-height: 16px;
  text-decoration: none;
  transition: background-color 160ms ease;
  animation: kalos-thinking-source-enter var(--kts-chip-duration) var(--kts-ease) backwards;
  animation-delay: calc(var(--kts-chip-lead) + min(var(--kts-chip-index, 0), 6) * var(--kts-chip-stagger));
}

.kalos-thinking-chip > span:last-child { min-width: 0; overflow-wrap: anywhere; }
.kalos-thinking-chip:is(a, button) { cursor: pointer; }
.kalos-thinking-chip:is(a, [tabindex]):is(:hover, :focus-visible) {
  background-color: var(--kts-chip-hover);
}

.kalos-thinking-source-icon {
  display: grid;
  place-items: center;
  flex: none;
  width: 14px;
  height: 14px;
  color: var(--kts-muted);
}

.kalos-thinking-source-icon > :is(img, svg) { width: 100%; height: 100%; object-fit: contain; }

.kalos-thinking-source-icon[data-brand] {
  overflow: hidden;
  border-radius: 4px;
  box-shadow: 0 0 0 .5px var(--kts-logo-edge);
}

.kalos-thinking-more {
  padding-inline: 8px;
  background: transparent;
  color: var(--kts-muted);
  box-shadow: inset 0 0 0 .5px var(--kts-more-edge);
  font-weight: 500;
}

.kalos-thinking-more:is(:hover, :focus-visible) {
  background: var(--kts-more-hover);
  color: var(--kts-ink);
}

.kalos-thinking-done { color: var(--kts-ink); font-weight: 500; }
.kalos-thinking-done .kalos-thinking-node { color: var(--kts-accent); }
.kalos-thinking-done .kalos-thinking-node > svg {
  width: 16px;
  height: 16px;
  animation: kalos-thinking-check var(--kts-check-duration) cubic-bezier(.34, 1.46, .64, 1) both;
}
.kalos-thinking-done path {
  stroke: var(--kts-on-accent);
  stroke-dasharray: 1;
  animation: kalos-thinking-draw var(--kts-tick-duration) var(--kts-tick-delay) var(--kts-ease) both;
}

.kalos-thinking-tooltip-positioner { z-index: 60; }

.kalos-thinking-tooltip {
  box-sizing: border-box;
  max-width: min(var(--available-width, 260px), 260px);
  padding: 4px 8px;
  border-radius: var(--kts-chip-radius);
  background: var(--kts-popup-surface);
  color: var(--kts-muted);
  box-shadow: var(--kts-popup-shadow);
  outline: none;
  font-size: 12px;
  line-height: 16px;
  overflow-wrap: anywhere;
  transition: opacity 140ms ease, translate 200ms var(--kts-ease);
}

.kalos-thinking-tooltip:is([data-starting-style], [data-ending-style]) { opacity: 0; translate: 0 4px; }
.kalos-thinking-tooltip[data-side="bottom"]:is([data-starting-style], [data-ending-style]) { translate: 0 -4px; }

@media (pointer: coarse) {
  .kalos-thinking-header, .kalos-thinking-chip { min-height: 32px; }
  .kalos-thinking-header .kalos-thinking-chevron { opacity: 1; }
}

@keyframes kalos-thinking-pixel {
  0%, 100% { opacity: .35; }
  50% { opacity: 1; }
}
@keyframes kalos-thinking-pulse {
  0%, 100% { opacity: .46; scale: .8; }
  50% { opacity: 1; scale: 1.14; }
}
@keyframes kalos-thinking-shimmer {
  from { background-position: 100% 0; }
  to { background-position: 0 0; }
}
@keyframes kalos-thinking-enter {
  from { opacity: 0; translate: 0 5px; }
}
@keyframes kalos-thinking-source-enter {
  from { opacity: 0; translate: 0 4px; scale: .92; }
}
@keyframes kalos-thinking-check {
  from { opacity: 0; scale: .55; }
}
@keyframes kalos-thinking-draw {
  from { stroke-dashoffset: 1; }
  to { stroke-dashoffset: 0; }
}
